    100*cv('Cs','HCN','w_405_150')[0]/cv('Cs','HCN','Fbroad')[0],100*cv('Cs','HCO+','w_405_150')[0]/cv('Cs','HCO+','Fbroad')[0],100*cv('C0','HCN','w_405_150')[0]/cv('C0','HCN','Fbroad')[0],
